"""Patches of docs/port-hl/cfg_rth9h.py, group head (case HEAD): see the configuration's header.

Round 1's case HEAD proved only the gzip branch (a call that passes the header); here every branch is proved
(src/proof/roundtrip/RTH9HHeadKit.v: wrap = 0, NEEDBITS(16) out of input, the zlib branch with head->done = -1)
and the case is assembled from them."""

_HEADKIT = 'Zlib.proof.roundtrip.RTHHEADKit6'
_CASE = 'Zlib.proof.roundtrip.RTHCaseHEAD6'

PATCHES = [
    (_HEADKIT, 'the branches the model excludes are\n   contradictions. *)',
     'here only the wrap test with wrap <> 0\n   and the gzip branch; the other branches are in RTH9HHeadKit.v. *)'),
    (_CASE, '(case_ok9v): the gzip branch;\n   the other branches contradict hpass (they leave the header modes with done <> 1). *)',
     '(case_ok9v), every branch:\n   wrap = 0, NEEDBITS(16) out of input, the gzip branch, the zlib branch (RTH9HHeadKit.v). *)'),
    (_CASE, 'Require Import Zlib.proof.inflate.HeadDefs5 Zlib.proof.inflate.Steps2.',
     'Require Import Zlib.proof.inflate.HeadDefs5 Zlib.proof.inflate.Steps2.\nRequire Import Zlib.proof.roundtrip.RTH9HHeadKit.'),
    (_CASE, "  intros Espec F HF m n HM HL W3 HD HI HP.\n  eapply semax_pre with\n    (P' := !! (h_done (m_h m) = 0) && (loop_stateH F m * (fun _ => hdr_tok F m * hd6 F m))).\n  { intros rho. simpl. apply andp_left2. apply andp_right; [ | apply derives_refl].\n    unfold hd6, head_rep6. rewrite !sepcon_andp_prop. apply andp_left1. apply prop_derives.\n    intros [H _]. exact H. }\n  apply semax_extract_prop. intros Hd0.\n  destruct (rthh_gzip _ _ _ HM HI Hd0 (proj1 W3) HP) as (Hw & HL1 & G).\n  pose proof (stepf2_HEAD (f_flush F) lenfix_list distfix_list m HM) as E0.\n  assert (E1: stepf2 (f_flush F) lenfix_list distfix_list m = IBrk (head_gzip_m (needbits 16 m))).\n  { rewrite E0, (c_HEAD_split m Hw HL1), G. reflexivity. }\n  assert (Hh: hd6 F (head_gzip_m (needbits 16 m)) = hd6 F m).\n  { destruct (rthh_nb_sh 4 16 m) as [S1 H1]. unfold hd6.\n    change (m_h (head_gzip_m (needbits 16 m))) with (m_h (needbits 16 m)). unfold needbits; rewrite H1.\n    symmetry. apply head_rep6_HEAD_FLAGS; [exact HM | reflexivity | ].\n    change (i_flags (m_s (head_gzip_m (needbits_f 4 16 m)))) with (i_flags (m_s (needbits_f 4 16 m))).\n    rewrite S1; reflexivity. }\n  eapply semax_post; [ | | | | apply semax_frame with (F := fun _ => hdr_tok F m * hd6 F m);\n                                 [ | apply (head_caseH F m HF HM HL W3 Hw HL1 G)]].\n  - intros rho. simpl. apply andp_left2. normalize.\n  - intros rho. simpl. apply andp_left2. normalize. rewrite E1 in H. inversion H; subst x; clear H.\n    apply (exp_right (head_gzip_m (needbits 16 m))). unfold post9, hd9.\n    replace (hdr_mode (m_mode (head_gzip_m (needbits 16 m)))) with true by reflexivity.\n    rewrite Hh. simpl. normalize. cancel.\n  - intros rho. simpl. apply andp_left2. normalize.\n  - intros vl rho. simpl. apply andp_left2. normalize. rewrite E1 in H. discriminate.\n  - intros rho te _. reflexivity.\n",
     "  intros Espec F HF m HM HL W3 HD HI.\n  eapply semax_pre with\n    (P' := !! (h_done (m_h m) = 0) && (loop_stateH F m * (fun _ => hdr_tok F m * hd6 F m))).\n  { intros rho. simpl. apply andp_left2. apply andp_right; [ | apply derives_refl].\n    unfold hd6, head_rep6. rewrite !sepcon_andp_prop. apply andp_left1. apply prop_derives.\n    intros [H _]. exact H. }\n  apply semax_extract_prop. intros Hd0.\n  pose proof (proj1 W3) as W.\n  pose proof (stepf2_HEAD (f_flush F) lenfix_list distfix_list m HM) as E0.\n  destruct (needbits_sh9 16 m) as [S1 H1].\n  destruct (Z.eq_dec (i_wrap (m_s m)) 0) as [Hw0 | Hw].\n  - (* wrap = 0: mode TYPEDO, the header left raw *)\n    apply (head_frame9 F m (set_mode m IM.TYPEDO)).\n    + rewrite E0. unfold c_HEAD2. rewrite Hw0. reflexivity.\n    + unfold hd6. sep_apply head_rep6_raw. Intros.\n      change (m_h m) with (m_h (set_mode m IM.TYPEDO)).\n      apply hd9_of_raw; [reflexivity | change (h_done (m_h m) <> 1); lia].\n    + apply head_case_lv9H; auto.\n  - destruct (m_leave (needbits 16 m) =? 1) eqn:Hl.\n    + (* NEEDBITS(16) out of input: mode HEAD, the partial header unchanged *)\n      apply Z.eqb_eq in Hl.\n      apply (head_frame9 F m (needbits 16 m)).\n      * rewrite E0. unfold c_HEAD2. rewrite (proj2 (Z.eqb_neq _ _) Hw). cbv zeta. rewrite Hl. reflexivity.\n      * unfold hd9, hd6. unfold m_mode. rewrite S1, H1. change (i_mode (m_s m)) with (m_mode m). rewrite HM.\n        apply derives_refl.\n      * apply head_case_lv9H; auto.\n    + apply Z.eqb_neq in Hl.\n      pose proof (mw9_leave _ (mwf9_needbits 16 m W ltac:(lia))) as WL.\n      assert (HL1: m_leave (needbits 16 m) = 0) by lia.\n      destruct (andb (negb (Z.land (i_wrap (m_s (needbits 16 m))) 2 =? 0)) (m_hold (needbits 16 m) =? 35615))\n        eqn:G.\n      * (* the gzip branch: mode FLAGS, the partial header unchanged *)\n        assert (E1: stepf2 (f_flush F) lenfix_list distfix_list m = IBrk (head_gzip_m (needbits 16 m))).\n        { rewrite E0, (c_HEAD_split m Hw HL1), G. reflexivity. }\n        apply (head_frame9 F m (head_gzip_m (needbits 16 m)) _ E1).\n        -- unfold hd9. replace (hdr_mode (m_mode (head_gzip_m (needbits 16 m)))) with true by reflexivity.\n           unfold hd6.\n           change (m_h (head_gzip_m (needbits 16 m))) with (m_h (needbits 16 m)). rewrite H1.\n           rewrite (head_rep6_HEAD_FLAGS _ _ _ _ _ (m_s m) (m_s (head_gzip_m (needbits 16 m))) (m_h m) HM);\n             [apply derives_refl | reflexivity | ].\n           change (i_flags (m_s (head_gzip_m (needbits 16 m)))) with (i_flags (m_s (needbits 16 m))).\n           rewrite S1; reflexivity.\n        -- apply (head_caseH_h9h F m HF HM HL W3 Hw HL1 G).\n      * (* the zlib branch *)\n        apply head_case_zlib9; auto.\n"),
]

# the model fact that a call passing the header takes the gzip branch: case HEAD now proves every branch
DROP = {_HEADKIT: ['rthh_gzip']}
